<section class="section light"><div class="container"><div class="post-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="post-card"><?php if(has_post_thumbnail()): ?><a href="<?php the_permalink(); ?>" tabindex="-1" aria-hidden="true"><?php the_post_thumbnail('large',['loading'=>'lazy','alt'=>rzz_content_image_details(get_the_ID())['alt']]); ?></a><?php else: ?><a href="<?php the_permalink(); ?>" tabindex="-1" aria-hidden="true"><img src="<?php echo esc_url(rzz_article_image(get_the_ID())); ?>" width="800" height="533" loading="lazy" decoding="async" <?php echo rzz_photo_attributes(rzz_content_image_details(get_the_ID(),rzz_article_image(get_the_ID()))); ?>></a><?php endif; ?><p class="eyebrow"><time datetime="<?php echo esc_attr(get_the_date(DATE_W3C)); ?>"><?php echo esc_html(get_the_date()); ?></time></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_the_excerpt()); ?></p><a class="text-link" href="<?php the_permalink(); ?>">Read more <?php echo rzz_arrow(); ?></a></article><?php endwhile;else: ?><div class="empty-state"><h2>More perspectives to come.</h2><p>Our legal insights will appear here. For advice on a particular matter, contact our team.</p></div><?php endif; ?></div><?php the_posts_pagination(); ?></div></section>